  const applyBackendResult = (data: PlanResponse) => {
    setBackendResult(data);
    if (Array.isArray(data?.assumptions)) {
      setAssumptions(
        data.assumptions.map((item: BackendAssumption) => ({
          field: item.field_name ?? "unknown",
          value:
            typeof item.assumed_value === "string"
              ? item.assumed_value
              : JSON.stringify(item.assumed_value),
          reason: item.reason ?? "",
        })),
      );
    } else {
      setAssumptions(defaultAssumptions);
    }

    if (Array.isArray(data?.issues)) {
      setIssues(
        data.issues.map((item: BackendIssue) => ({
          severity: item.severity === "error" ? "error" : "warning",
          message: item.message ?? "Unknown issue",
          code: typeof item.code === "string" ? item.code : undefined,
          context: item.context && typeof item.context === "object" ? item.context : undefined,
        })),
      );
    } else {
      setIssues([]);
    }

    const report = data?.final_plan?.meta?.reactive_update_report;
    if (report?.partial_rerun_executed) {
      const completedStages = new Set(
        [
          ...(report.post_rerun_completed_stages ?? []),
          ...(report.post_rerun_stage_status ?? [])
            .filter((row) => row.completed)
            .map((row) => row.stage ?? ""),
        ].filter(Boolean),
      );
      const staleAfter = new Set(report.post_rerun_stale_outputs ?? []);
      const impacted = new Set(report.impacted_stages ?? []);
      setSystemStatuses((prev) => {
        const next = { ...prev };
        (Object.entries(REACTIVE_SYSTEM_STAGE_MAP) as Array<[EngineeringSystemKey, string[]]>).forEach(
          ([system, stages]) => {
            const touchedStages = stages.filter((stage) => impacted.has(stage));
            if (!touchedStages.length) return;
            const cleared = touchedStages.every(
              (stage) => completedStages.has(stage) && !staleAfter.has(stage),
            );
            if (cleared) {
              next[system] = "fresh";
            }
          },
        );
        return next;
      });
    }
  };

  const appendChatMessage = (
    role: ChatMessage["role"],
    content: string,
    kind: ChatMessage["kind"] = "message",
    feedback?: ChatMessage["feedback"],
  ) => {
    setChatMessages((current) => {
      const phaseTag =
        role === "assistant" || role === "system"
          ? currentPhaseLabelRef.current || undefined
          : undefined;
      const next = [
        ...current,
        createChatMessage(role, content, kind, feedback, phaseTag),
      ];
      chatMessagesRef.current = next;
      return next;
    });
  };


  const setMessageFeedback = async (
    messageId: string,
    feedback: ChatMessage["feedback"],
  ) => {
    if (!token || !feedback) return;
    const thread = chatMessagesRef.current;
    const idx = thread.findIndex((message) => message.id === messageId);
    if (idx < 0) return;
    const target = thread[idx];
    const prevUser = [...thread]
      .slice(0, idx)
      .reverse()
      .find((message) => message.role === "user");
    const userMessage = prevUser?.content ?? "";

    setChatMessages((current) => {
      const next = current.map((message) =>
        message.id === messageId ? { ...message, feedback } : message,
      );
      chatMessagesRef.current = next;
      return next;
    });

    try {
      await postJson<{ success: boolean }>(
        "/api/chat/feedback",
        {
          project_id: currentProject?.project_id ?? null,
          message_id: messageId,
          feedback,
          message: userMessage,
          assistant_message: target.content,
          context: buildChatDecisionContext({}, userMessage),
        },
        { token },
      );
    } catch {
      // Feedback logging should never block chat UX.
    }
  };

