  const controlsHealthStatus = Object.values(systemStatuses).some((value) => value === "fresh") ? "ok" : "review";
  const panelStatus = (target: SidePanelKey): SidebarStatus => {
    if (target === "dashboard" || target === "analysis") {
      return issues.length || analysisIssues.length || hasHardSystemBlock ? "review" : backendResult ? "ok" : "idle";
    }
    if (target === "site_existing" || target === "data") {
      return siteScaleLocked || Boolean(siteInputs?.geocode?.lat && siteInputs?.geocode?.lng) ? "ok" : "review";
    }
    if (target === "import_survey" || target === "files") {
      return hasTerrainSource || surveyPreviewPoints.length || uploadedImagePreviewUrl || uploadedImageApiUrl || mapSnapshotPath
        ? "ok"
        : "review";
    }
    if (target === "model" || target === "layers") {
      return placedObjectCount > 0 || planPreviewUrl ? "ok" : "idle";
    }
    if (target === "objects" || target === "details") {
      return buildingPlacements.length > 0 ? "ok" : "idle";
    }
    if (target === "generate") {
      return controlsHealthStatus;
    }
    if (target === "grading") {
      return siteTooLargeForGrading ? "block" : hasTerrainSource || systemStatuses.grading === "fresh" ? "ok" : "review";
    }
    if (target === "drainage") {
      return hasHardSystemBlock ? "block" : hasBasinPlaced || systemStatuses.drainage === "fresh" ? "ok" : "review";
    }
    if (target === "sanitary" || target === "water" || target === "utilities") {
      return hasHardSystemBlock ? "block" : utilities || systemStatuses.utilities === "fresh" ? "ok" : "review";
    }
    if (target === "roadway") {
      return roads || systemStatuses.roads === "fresh" ? "ok" : "review";
    }
    if (target === "landscape") {
      return buildingPlacements.some((value) => ["open_space", "amenity", "pool", "sidewalk"].includes(value.type ?? ""))
        ? "ok"
        : "idle";
    }
    if (target === "reports" || target === "quantities" || target === "deliverables") {
      return backendResult ? "ok" : "idle";
    }
    if (target === "standards") {
      return minSlopePct || maxRoadGradePct || pipeMinSlopePct || maxAdaCrossSlopePct ? "ok" : "review";
    }
    if (target === "templates") {
      return customerTemplateBlockerCount > 0 ? "review" : customerTemplates ? "ok" : "idle";
    }
    if (target === "catalogs") {
      return Number(utilityCatalog?.summary?.review_required_count ?? 0) > 0 ? "review" : utilityCatalog ? "ok" : "idle";
    }
    if (target === "libraries" || target === "settings" || target === "chat" || target === "projects") {
      return "ok";
    }
    return "idle";
  };
  const sidebarModeStatus = (mode: WorkspaceMode): SidebarStatus => {
    if (mode === "trust") return "ok";
    if (mode === "dashboard") return panelStatus("dashboard");
    if (mode === "setup") return siteScaleLocked ? "ok" : "review";
    if (mode === "canvas") return panelStatus("model");
    if (mode === "layers") return panelStatus("layers");
    if (mode === "deliver") return String(previewReview?.release_status || "review").toLowerCase() === "blocked" ? "review" : panelStatus("deliverables");
    if (mode === "data") return panelStatus("data");
    if (mode === "settings") return panelStatus("settings");
    return "idle";
  };
	  const primaryWorkflowGroups: Record<PrimaryWorkflowKey, SidePanelKey[]> = {
	    setup: ["site_existing", "import_survey", "data", "standards"],
	    draw: ["model", "layers", "files"],
	    objects: ["objects", "model", "details"],
	    design: [
	      "generate",
	      "grading",
	      "drainage",
	      "sanitary",
	      "water",
	      "utilities",
	      "roadway",
	      "landscape",
	      "system_grading",
	      "system_storm",
	      "system_sanitary",
	      "system_water",
	      "system_roadway",
	      "system_utilities",
	      "system_landscape",
	    ],
	    analyze: ["analysis", "quantities", "jobs", "catalogs"],
    deliver: ["deliverables", "reports", "settings", "chat"],
	  };
	  const activePrimaryWorkflowKey =
	    (Object.entries(primaryWorkflowGroups).find(([, panels]) =>
	      sidePanelForRender ? panels.includes(sidePanelForRender) : false,
	    )?.[0] as PrimaryWorkflowKey | undefined) ??
	    (activeWorkspaceMode === "setup"
	      ? "setup"
	      : activeWorkspaceMode === "canvas" || activeWorkspaceMode === "layers"
	        ? "draw"
        : activeWorkspaceMode === "deliver"
	            ? "deliver"
	            : activeWorkspaceMode === "data"
	              ? "setup"
	              : "analyze");
	  const primaryWorkflowItems: PrimaryWorkflowItem[] = [
	    {
	      key: "setup",
	      label: "Setup",
	      caption: "Address, boundary, sources",
	      panel: "site_existing",
	      icon: MapPinned,
	      status: sidebarModeStatus("setup"),
	      metric: siteScaleLocked ? "Site locked" : "Needs boundary",
	    },
	    {
	      key: "draw",
	      label: "Draw",
	      caption: "Canvas and drafting",
	      panel: "objects",
	      icon: Box,
	      status: siteScaleLocked ? panelStatus("objects") : "review",
	      metric: `${placedObjects.length} objects`,
	    },
	    {
	      key: "objects",
	      label: "Object Manager",
	      caption: "Objects, layers, tools",
	      panel: "objects",
	      icon: Layers,
	      status: panelStatus("objects"),
	      metric: `${placedObjects.length} placed / ${pendingPlacementObjects.length} pending`,
	    },
	    {
	      key: "design",
	      label: "Generate",
	      caption: "Grading, storm, utilities",
	      panel: "generate",
	      icon: SlidersHorizontal,
	      status: hasHardSystemBlock ? "block" : controlsHealthStatus,
	      metric: `${Object.values(systemStatuses).filter((status) => status === "fresh").length} fresh`,
	    },
	    {
	      key: "analyze",
	      label: "Project Health",
	      caption: "Issues, quantities, jobs",
	      panel: "analysis",
	      icon: Gauge,
	      status: issues.length || analysisIssues.length ? "review" : backendResult ? "ok" : "idle",
	      metric: `${issues.length + analysisIssues.length} issue${issues.length + analysisIssues.length === 1 ? "" : "s"}`,
	    },
	    {
	      key: "deliver",
	      label: "Deliver",
	      caption: "Sheets and exports",
	      panel: "deliverables",
	      icon: FileText,
	      status: sidebarModeStatus("deliver"),
	      metric: getExportBlockReason() ? "Export needs input" : "Review package",
	    },
	  ];
  const handleCancelActiveTool = useCallback(() => {
    if (shortcutsOverlayOpen) {
      setShortcutsOverlayOpen(false);
      return;
    }
    if (activeSidePanel === "projects" && document.querySelector('[data-testid="projects-drawer"]')) {
      handleCloseSidePanel();
      updateProjectStatus({
        state: "ready",
        area: "projects",
        title: "Projects closed",
        detail: "Projects drawer closed.",
        nextAction: "Continue from the canvas or use / for commands.",
      });
      return;
    }
    if (previewFullscreenOpen) setPreviewFullscreenOpen(false);
    setPlacementModeEnabled(false);
    setActivePlacementId(null);
    setSelectedObjectIds([]);
    setPendingClarification(null);
    setPreviewInteraction("static");
    setCadToolRequest({ id: Date.now() + Math.random(), tool: "select" });
    updateProjectStatus({
      state: "ready",
      area: "chat",
      title: "Active tool cancelled",
      detail: "Active drawing/tool state cancelled.",
      nextAction: "Select another tool, continue drawing, or use the command bar.",
    });
  }, [activeSidePanel, handleCloseSidePanel, previewFullscreenOpen, shortcutsOverlayOpen, updateProjectStatus]);

  const handleDeleteSelectedObject = useCallback(() => {
    if (selectedObjectIds.length > 1) {
      handleObjectManagerBulkDelete();
      return;
    }
    const target = activePlacementId
      ? buildingPlacements.find((item) => item.id === activePlacementId)
      : selectedObjectIds[0]
        ? buildingPlacements.find((item) => item.id === selectedObjectIds[0])
        : null;
    if (!target) {
      const message = "Select an editable object before deleting.";
      setObjectManagerStatusMessage(message);
      updateProjectStatus({
        state: "blocked",
        area: "chat",
        title: "Delete needs a selection",
        detail: "No object is selected.",
        nextAction: "Select an editable draft object, then press Delete again.",
      });
      appendChatMessage("assistant", message, "status");
      return;
    }
    if (target.type === "site" || target.capabilities?.deletable === false) {
      const message = `${target.label} cannot be deleted from shortcuts.`;
      setObjectManagerStatusMessage(message);
      updateProjectStatus({
        state: "blocked",
        area: "chat",
        title: "Open Object Manager",
        detail: `${target.label} cannot be deleted from shortcuts.`,
        nextAction: "Open Object Manager to review object locks and capabilities.",
      });
      appendChatMessage("assistant", message, "status");
      return;
    }
    if (target.locked) {
      const message = `Unlock ${target.label} before deleting it.`;
      setObjectManagerStatusMessage(message);
      updateProjectStatus({
        state: "blocked",
        area: "chat",
        title: "Delete needs unlock",
        detail: `Unlock ${target.label} before deleting it.`,
        nextAction: "Open Object Manager, unlock the object if appropriate, then delete.",
      });
      appendChatMessage("assistant", message, "status");
      return;
    }
    handleRemoveBuilding(target.id);
    appendChatMessage("assistant", `Deleted ${target.label}.`, "status");
    updateProjectStatus({
      state: "stale",
      area: "chat",
      title: "Object deleted",
      detail: `Deleted ${target.label}. Generated systems may be stale.`,
      nextAction: "Undo if needed, or rerun affected generated systems.",
    });
  }, [
    activePlacementId,
    appendChatMessage,
    buildingPlacements,
    handleObjectManagerBulkDelete,
    handleRemoveBuilding,
    selectedObjectIds,
    updateProjectStatus,
  ]);

  const handleCopySelectedObject = useCallback(() => {
    if (selectedObjectIds.length > 1) {
      const targets = buildingPlacements.filter((item) => selectedObjectIds.includes(item.id));
      const editable = targets.filter((item) => !getObjectEditBlocker(item, "copy"));
      const blockedCount = targets.length - editable.length;
      if (!editable.length) {
        reportObjectActionBlocker("Select editable draft objects before copying.");
        updateProjectStatus({
          state: "blocked",
          area: "chat",
          title: "Copy needs editable objects",
          detail: "Selected objects are locked, source-only, or required project evidence.",
          nextAction: "Select editable draft objects, then press Cmd/Ctrl+C again.",
        });
        return;
      }
      setObjectClipboard(editable.map(cloneBuildingPlacementForUndo));
      const message = `Copied ${editable.length} selected draft object${editable.length === 1 ? "" : "s"}${blockedCount ? `; ${blockedCount} blocked.` : "."}`;
      setObjectManagerStatusMessage(message);
      setStatusMessage(message);
      updateProjectStatus({
        state: "ready",
        area: "chat",
        title: "Objects copied",
        detail: message,
        nextAction: "Press Cmd/Ctrl+V or use Paste to place draft duplicates.",
      });
      return;
    }
    const target = activePlacementId
      ? buildingPlacements.find((item) => item.id === activePlacementId)
      : selectedObjectIds[0]
        ? buildingPlacements.find((item) => item.id === selectedObjectIds[0])
        : null;
    if (!target) {
      reportObjectActionBlocker("Select an editable draft object before copying.");
      updateProjectStatus({
        state: "blocked",
        area: "chat",
        title: "Copy needs a selection",
        detail: "No object is selected.",
        nextAction: "Select an editable draft object, then press Cmd/Ctrl+C again.",
      });
      return;
    }
    handleObjectManagerCopy(target);
    updateProjectStatus({
      state: "ready",
      area: "chat",
      title: "Object copied",
      detail: `Copied ${target.label}.`,
      nextAction: "Press Cmd/Ctrl+V or use Paste to place a draft duplicate.",
    });
  }, [
    activePlacementId,
    buildingPlacements,
    cloneBuildingPlacementForUndo,
    handleObjectManagerCopy,
    reportObjectActionBlocker,
    selectedObjectIds,
    updateProjectStatus,
  ]);

  const handlePasteSelectedObject = useCallback(() => {
    handleObjectManagerPaste();
    const clipboardCount = objectClipboard.length;
    updateProjectStatus({
      state: clipboardCount ? "stale" : "blocked",
      area: "chat",
      title: clipboardCount ? (clipboardCount === 1 ? "Object pasted" : "Objects pasted") : "Paste needs a copied object",
      detail: clipboardCount
        ? clipboardCount === 1
          ? `Pasted ${objectClipboard[0].label} as an editable draft duplicate.`
          : `Pasted ${clipboardCount} copied draft objects as editable draft duplicates.`
        : "Copy an editable object before pasting.",
      nextAction: clipboardCount
        ? "Move, rename, or regenerate affected systems after review."
        : "Select an editable draft object, then press Cmd/Ctrl+C.",
    });
  }, [handleObjectManagerPaste, objectClipboard, updateProjectStatus]);

  const handleUndoDraftAction = useCallback(() => {
    const draftAction = lastDraftActionRef.current ?? lastDraftAction;
    const clearDraftAction = () => {
      lastDraftActionRef.current = null;
      clearDraftUndoAction();
    };
    if (!draftAction) {
      const message = "Nothing available to undo yet.";
      updateProjectStatus({
        state: "blocked",
        area: "chat",
        title: "Undo not available yet",
        detail: "No supported draft action is available to undo.",
        nextAction: "Continue editing; the next supported draft add/delete can be undone.",
      });
      appendChatMessage("assistant", message, "status");
      return;
    }
    recordDraftRedoAction(draftAction);
    if (draftAction.action === "add") {
      setBuildingPlacements((prev) => prev.filter((item) => item.id !== draftAction.object.id));
      setActivePlacementId((prev) => (prev === draftAction.object.id ? null : prev));
      setPlacementModeEnabled(false);
      const message = `Undo: removed ${draftAction.object.label}.`;
      setObjectManagerStatusMessage(message);
      pushRecoveryMessage(message);
      updateProjectStatus({
        state: "stale",
        area: "chat",
        title: "Undo complete",
        detail: `Undo removed ${draftAction.object.label}.`,
        nextAction: "Review objects, then rerun affected generated systems if needed.",
      });
      appendChatMessage("assistant", message, "status");
      recordRecentChange({
        type: "object_deleted",
        label: "Undo removed object",
        detail: `${draftAction.object.label} was removed by undo.`,
        undoBlockedReason: "This is already an undo result.",
      });
      clearDraftAction();
      return;
    }
    if (draftAction.action === "add_many") {
      const createdIds = new Set(draftAction.objects.map((item) => item.id));
      setBuildingPlacements((prev) => prev.filter((item) => !createdIds.has(item.id)));
      setSelectedObjectIds((prev) => prev.filter((id) => !createdIds.has(id)));
      setActivePlacementId((prev) => (prev && createdIds.has(prev) ? null : prev));
      setPlacementModeEnabled(false);
      draftAction.objects.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: removed ${draftAction.objects.length} draft objects from ${draftAction.label}.`);
      appendChatMessage("assistant", `Undo: removed ${draftAction.objects.length} draft objects from ${draftAction.label}.`, "status");
      recordRecentChange({
        type: "object_deleted",
        label: "Undo removed objects",
        detail: `${draftAction.objects.length} draft objects were removed by undo.`,
        undoBlockedReason: "This is already an undo result.",
      });
      clearDraftAction();
      return;
    }
    if (draftAction.action === "delete_many") {
      const restoredIds = new Set(draftAction.objects.map((item) => item.id));
      setBuildingPlacements((prev) => [
        ...prev.filter((item) => !restoredIds.has(item.id)),
        ...draftAction.objects.map((item) => ({ ...item })),
      ]);
      setSelectedObjectIds(draftAction.objects.map((item) => item.id));
      setActivePlacementId(draftAction.objects[0]?.id ?? null);
      draftAction.objects.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: restored ${draftAction.objects.length} draft objects from ${draftAction.label}.`);
      appendChatMessage("assistant", `Undo: restored ${draftAction.objects.length} draft objects from ${draftAction.label}.`, "status");
      recordRecentChange({
        type: "object_added",
        label: "Undo restored deleted objects",
        detail: `${draftAction.objects.length} draft objects were restored by undo.`,
        undoBlockedReason: "This is already an undo result.",
      });
      clearDraftAction();
      return;
    }
    if (draftAction.action === "update") {
      setBuildingPlacements((prev) =>
        prev.map((item) => (item.id === draftAction.objectId ? { ...draftAction.before } : item)),
      );
      setActivePlacementId(draftAction.objectId);
      markSystemsStale(systemsImpactedByPlacement(draftAction.before));
      pushRecoveryMessage(`Undo: restored previous state for ${draftAction.before.label}.`);
      appendChatMessage("assistant", `Undo: restored previous state for ${draftAction.before.label}.`, "status");
      recordRecentChange({
        type: "object_style_changed",
        label: "Undo restored object",
        detail: `${draftAction.before.label} was restored to its previous draft state.`,
        undoBlockedReason: "This is already an undo result.",
      });
      clearDraftAction();
      return;
    }
    if (draftAction.action === "combine") {
      const sourceById = new Map(draftAction.hiddenSources.map((item) => [item.id, item]));
      setBuildingPlacements((prev) =>
        prev
          .filter((item) => item.id !== draftAction.object.id)
          .map((item) => (sourceById.has(item.id) ? { ...sourceById.get(item.id)! } : item)),
      );
      setSelectedObjectIds(draftAction.hiddenSources.map((item) => item.id));
      setActivePlacementId(draftAction.hiddenSources[0]?.id ?? null);
      draftAction.hiddenSources.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: restored ${draftAction.hiddenSources.length} source objects from ${draftAction.label}.`);
      appendChatMessage("assistant", `Undo: restored ${draftAction.hiddenSources.length} source objects from ${draftAction.label}.`, "status");
      recordRecentChange({
        type: "object_style_changed",
        label: "Undo restored combined sources",
        detail: `${draftAction.hiddenSources.length} source objects were restored and ${draftAction.object.label} was removed.`,
        undoBlockedReason: "This is already an undo result.",
      });
      clearDraftAction();
      return;
    }
    if (draftAction.action === "explode") {
      const beforeSourceById = new Map(draftAction.beforeSources.map((item) => [item.id, item]));
      setBuildingPlacements((prev) => [
        ...prev
          .filter((item) => item.id !== draftAction.object.id)
          .map((item) => (beforeSourceById.has(item.id) ? { ...beforeSourceById.get(item.id)! } : item)),
        { ...draftAction.object },
      ]);
      setSelectedObjectIds([draftAction.object.id]);
      setActivePlacementId(draftAction.object.id);
      markSystemsStale(systemsImpactedByPlacement(draftAction.object));
      pushRecoveryMessage(`Undo: restored ${draftAction.object.label} after ${draftAction.label}.`);
      appendChatMessage("assistant", `Undo: restored ${draftAction.object.label} after ${draftAction.label}.`, "status");
      recordRecentChange({
        type: "object_added",
        label: "Undo restored combined object",
        detail: `${draftAction.object.label} was restored and source pieces were hidden again.`,
        undoBlockedReason: "This is already an undo result.",
      });
      clearDraftAction();
      return;
    }
    if (draftAction.action === "bulk_update") {
      const beforeById = new Map(draftAction.before.map((item) => [item.id, item]));
      setBuildingPlacements((prev) =>
        prev.map((item) => (beforeById.has(item.id) ? { ...beforeById.get(item.id)! } : item)),
      );
      const visibleBefore = draftAction.before.filter((item) => !item.meta?.ui_hidden);
      setSelectedObjectIds(visibleBefore.map((item) => item.id));
      setActivePlacementId(visibleBefore[0]?.id ?? null);
      draftAction.before.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: restored ${draftAction.before.length} draft objects from ${draftAction.label}.`);
      appendChatMessage("assistant", `Undo: restored ${draftAction.before.length} draft objects from ${draftAction.label}.`, "status");
      recordRecentChange({
        type: "object_style_changed",
        label: "Undo restored objects",
        detail: `${draftAction.before.length} draft objects were restored to their previous state.`,
        undoBlockedReason: "This is already an undo result.",
      });
      clearDraftAction();
      return;
    }
    handleRestoreBuilding(draftAction.object);
    appendChatMessage("assistant", `Undo: restored ${draftAction.object.label}.`, "status");
    updateProjectStatus({
      state: "stale",
      area: "chat",
      title: "Undo complete",
      detail: `Undo restored ${draftAction.object.label}.`,
      nextAction: "Review objects, then rerun affected generated systems if needed.",
    });
    clearDraftAction();
  }, [
    clearDraftUndoAction,
    handleRestoreBuilding,
    lastDraftAction,
    markSystemsStale,
    pushRecoveryMessage,
    recordRecentChange,
    recordDraftRedoAction,
    systemsImpactedByPlacement,
    updateProjectStatus,
  ]);

  const handleRedoDraftAction = useCallback(() => {
    const redoAction = redoDraftActionRef.current ?? redoDraftAction;
    if (!redoAction) {
      const message = "Nothing available to redo yet.";
      setObjectManagerStatusMessage(message);
      pushRecoveryMessage(message);
      appendChatMessage("assistant", message, "status");
      return;
    }
    const finishRedo = (message: string) => {
      recordDraftUndoAction(redoAction);
      setObjectManagerStatusMessage(message);
      setStatusMessage(message);
      pushRecoveryMessage(message);
      appendChatMessage("assistant", message, "status");
    };
    if (redoAction.action === "add") {
      setBuildingPlacements((prev) =>
        prev.some((item) => item.id === redoAction.object.id) ? prev : [...prev, { ...redoAction.object }],
      );
      setSelectedObjectIds([redoAction.object.id]);
      setActivePlacementId(redoAction.object.id);
      setPlacementModeEnabled(false);
      markSystemsStale(systemsImpactedByPlacement(redoAction.object));
      finishRedo(`Redo: restored ${redoAction.object.label}.`);
      return;
    }
    if (redoAction.action === "add_many") {
      const createdIds = new Set(redoAction.objects.map((item) => item.id));
      setBuildingPlacements((prev) => [
        ...prev.filter((item) => !createdIds.has(item.id)),
        ...redoAction.objects.map((item) => ({ ...item })),
      ]);
      setSelectedObjectIds(redoAction.objects.map((item) => item.id));
      setActivePlacementId(redoAction.objects[0]?.id ?? null);
      redoAction.objects.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      finishRedo(`Redo: restored ${redoAction.objects.length} draft objects from ${redoAction.label}.`);
      return;
    }
    if (redoAction.action === "delete") {
      setBuildingPlacements((prev) => prev.filter((item) => item.id !== redoAction.object.id));
      setSelectedObjectIds((prev) => prev.filter((id) => id !== redoAction.object.id));
      setActivePlacementId((prev) => (prev === redoAction.object.id ? null : prev));
      markSystemsStale(systemsImpactedByPlacement(redoAction.object));
      finishRedo(`Redo: deleted ${redoAction.object.label}.`);
      return;
    }
    if (redoAction.action === "delete_many") {
      const deletedIds = new Set(redoAction.objects.map((item) => item.id));
      setBuildingPlacements((prev) => prev.filter((item) => !deletedIds.has(item.id)));
      setSelectedObjectIds((prev) => prev.filter((id) => !deletedIds.has(id)));
      setActivePlacementId((prev) => (prev && deletedIds.has(prev) ? null : prev));
      redoAction.objects.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      finishRedo(`Redo: deleted ${redoAction.objects.length} draft objects from ${redoAction.label}.`);
      return;
    }
    if (redoAction.action === "update") {
      setBuildingPlacements((prev) =>
        prev.map((item) => (item.id === redoAction.objectId ? { ...redoAction.after } : item)),
      );
      setSelectedObjectIds([redoAction.objectId]);
      setActivePlacementId(redoAction.objectId);
      markSystemsStale(systemsImpactedByPlacement(redoAction.after));
      finishRedo(`Redo: restored edited state for ${redoAction.after.label}.`);
      return;
    }
    if (redoAction.action === "combine") {
      const sourceIds = new Set(redoAction.hiddenSources.map((item) => item.id));
      setBuildingPlacements((prev) => [
        ...prev
          .filter((item) => item.id !== redoAction.object.id)
          .map((item) =>
            sourceIds.has(item.id)
              ? {
                  ...item,
                  meta: {
                    ...(item.meta ?? {}),
                    ui_hidden: true,
                    combined_into_object_id: redoAction.object.id,
                    combined_into_label: redoAction.object.label,
                  },
                }
              : item,
          ),
        { ...redoAction.object },
      ]);
      setSelectedObjectIds([redoAction.object.id]);
      setActivePlacementId(redoAction.object.id);
      markSystemsStale(systemsImpactedByPlacement(redoAction.object));
      finishRedo(`Redo: recombined ${redoAction.hiddenSources.length} source objects into ${redoAction.object.label}.`);
      return;
    }
    if (redoAction.action === "explode") {
      const afterSourceById = new Map(redoAction.afterSources.map((item) => [item.id, item]));
      setBuildingPlacements((prev) =>
        prev
          .filter((item) => item.id !== redoAction.object.id)
          .map((item) => (afterSourceById.has(item.id) ? { ...afterSourceById.get(item.id)! } : item)),
      );
      setSelectedObjectIds(redoAction.afterSources.map((item) => item.id));
      setActivePlacementId(redoAction.afterSources[0]?.id ?? null);
      markSystemsStale(systemsImpactedByPlacement(redoAction.object));
      finishRedo(`Redo: exploded ${redoAction.object.label} into ${redoAction.afterSources.length} source pieces.`);
      return;
    }
    if (redoAction.action === "bulk_update" && redoAction.after?.length) {
      const afterById = new Map(redoAction.after.map((item) => [item.id, item]));
      setBuildingPlacements((prev) =>
        prev.map((item) => (afterById.has(item.id) ? { ...afterById.get(item.id)! } : item)),
      );
      const visibleAfter = redoAction.after.filter((item) => !item.meta?.ui_hidden);
      setSelectedObjectIds(visibleAfter.map((item) => item.id));
      setActivePlacementId(visibleAfter[0]?.id ?? null);
      redoAction.after.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      finishRedo(`Redo: reapplied ${redoAction.after.length} draft objects from ${redoAction.label}.`);
      return;
    }
    const message = `Redo not available: ${redoAction.action === "bulk_update" ? `${redoAction.label} does not have an after snapshot yet.` : "this draft action cannot be reapplied safely."}`;
    setObjectManagerStatusMessage(message);
    pushRecoveryMessage(message);
    appendChatMessage("assistant", message, "status");
  }, [
    appendChatMessage,
    markSystemsStale,
    pushRecoveryMessage,
    recordDraftUndoAction,
    redoDraftAction,
    systemsImpactedByPlacement,
  ]);

  const handleUndoRecentChange = useCallback((change: RecentChange) => {
    if (!change.undo) {
      const message = `Undo not available: ${change.undoBlockedReason || "this recent change does not have a reversible draft snapshot."}`;
      pushRecoveryMessage(message);
      appendChatMessage("assistant", message, "status");
      return;
    }
    const undo = change.undo;
    recordDraftRedoAction(undo);
    if (undo.action === "add") {
      setBuildingPlacements((prev) => prev.filter((item) => item.id !== undo.object.id));
      setActivePlacementId((prev) => (prev === undo.object.id ? null : prev));
      setPlacementModeEnabled(false);
      markSystemsStale(systemsImpactedByPlacement(undo.object));
      pushRecoveryMessage(`Undo: removed ${undo.object.label}.`);
      recordRecentChange({
        type: "object_deleted",
        label: "Undo removed object",
        detail: `${undo.object.label} was removed by undo.`,
        undoBlockedReason: "This is already an undo result.",
      });
      return;
    }
    if (undo.action === "add_many") {
      const createdIds = new Set(undo.objects.map((item) => item.id));
      setBuildingPlacements((prev) => prev.filter((item) => !createdIds.has(item.id)));
      setSelectedObjectIds((prev) => prev.filter((id) => !createdIds.has(id)));
      setActivePlacementId((prev) => (prev && createdIds.has(prev) ? null : prev));
      setPlacementModeEnabled(false);
      undo.objects.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: removed ${undo.objects.length} draft objects from ${undo.label}.`);
      recordRecentChange({
        type: "object_deleted",
        label: "Undo removed objects",
        detail: `${undo.objects.length} draft objects were removed by undo.`,
        undoBlockedReason: "This is already an undo result.",
      });
      return;
    }
    if (undo.action === "delete_many") {
      const restoredIds = new Set(undo.objects.map((item) => item.id));
      setBuildingPlacements((prev) => [
        ...prev.filter((item) => !restoredIds.has(item.id)),
        ...undo.objects.map((item) => ({ ...item })),
      ]);
      setSelectedObjectIds(undo.objects.map((item) => item.id));
      setActivePlacementId(undo.objects[0]?.id ?? null);
      undo.objects.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: restored ${undo.objects.length} draft objects from ${undo.label}.`);
      recordRecentChange({
        type: "object_added",
        label: "Undo restored deleted objects",
        detail: `${undo.objects.length} draft objects were restored by undo.`,
        undoBlockedReason: "This is already an undo result.",
      });
      return;
    }
    if (undo.action === "delete") {
      handleRestoreBuilding(undo.object);
      return;
    }
    if (undo.action === "combine") {
      const sourceById = new Map(undo.hiddenSources.map((item) => [item.id, item]));
      setBuildingPlacements((prev) =>
        prev
          .filter((item) => item.id !== undo.object.id)
          .map((item) => (sourceById.has(item.id) ? { ...sourceById.get(item.id)! } : item)),
      );
      setSelectedObjectIds(undo.hiddenSources.map((item) => item.id));
      setActivePlacementId(undo.hiddenSources[0]?.id ?? null);
      undo.hiddenSources.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: restored ${undo.hiddenSources.length} source objects from ${undo.label}.`);
      recordRecentChange({
        type: "object_style_changed",
        label: "Undo restored combined sources",
        detail: `${undo.hiddenSources.length} source objects were restored and ${undo.object.label} was removed.`,
        undoBlockedReason: "This is already an undo result.",
      });
      return;
    }
    if (undo.action === "explode") {
      const beforeSourceById = new Map(undo.beforeSources.map((item) => [item.id, item]));
      setBuildingPlacements((prev) => [
        ...prev
          .filter((item) => item.id !== undo.object.id)
          .map((item) => (beforeSourceById.has(item.id) ? { ...beforeSourceById.get(item.id)! } : item)),
        { ...undo.object },
      ]);
      setSelectedObjectIds([undo.object.id]);
      setActivePlacementId(undo.object.id);
      markSystemsStale(systemsImpactedByPlacement(undo.object));
      pushRecoveryMessage(`Undo: restored ${undo.object.label} after ${undo.label}.`);
      recordRecentChange({
        type: "object_added",
        label: "Undo restored combined object",
        detail: `${undo.object.label} was restored and source pieces were hidden again.`,
        undoBlockedReason: "This is already an undo result.",
      });
      return;
    }
    if (undo.action === "bulk_update") {
      const beforeById = new Map(undo.before.map((item) => [item.id, item]));
      setBuildingPlacements((prev) =>
        prev.map((item) => (beforeById.has(item.id) ? { ...beforeById.get(item.id)! } : item)),
      );
      const visibleBefore = undo.before.filter((item) => !item.meta?.ui_hidden);
      setSelectedObjectIds(visibleBefore.map((item) => item.id));
      setActivePlacementId(visibleBefore[0]?.id ?? null);
      undo.before.forEach((item) => markSystemsStale(systemsImpactedByPlacement(item)));
      pushRecoveryMessage(`Undo: restored ${undo.before.length} draft objects from ${undo.label}.`);
      recordRecentChange({
        type: "object_style_changed",
        label: "Undo restored objects",
        detail: `${undo.before.length} draft objects were restored to their previous state.`,
        undoBlockedReason: "This is already an undo result.",
      });
      return;
    }
    setBuildingPlacements((prev) =>
      prev.map((item) => (item.id === undo.objectId ? { ...undo.before } : item)),
    );
    setActivePlacementId(undo.objectId);
    markSystemsStale(systemsImpactedByPlacement(undo.before));
    pushRecoveryMessage(`Undo: restored previous state for ${undo.before.label}.`);
    recordRecentChange({
      type: "object_style_changed",
      label: "Undo restored object",
      detail: `${undo.before.label} was restored to its previous draft state.`,
      undoBlockedReason: "This is already an undo result.",
    });
  }, [
    appendChatMessage,
    handleRestoreBuilding,
    markSystemsStale,
    pushRecoveryMessage,
    recordDraftRedoAction,
    recordRecentChange,
    systemsImpactedByPlacement,
  ]);

