      updateProjectStatus({
        state: "blocked",
        area: "projects",
        title: "Save needs sign-in",
        detail: "Sign in/connect backend to save projects.",
        nextAction: "Sign in or reconnect backend, then press Cmd/Ctrl+S again.",
      });
