                            onBulkMoveYChange={setBulkMoveY}
                            onMoveSelected={handleObjectManagerBulkMove}
                            onCopyByOffset={handleObjectManagerBulkCopyByOffset}
                            onBulkMoveToXChange={setBulkMoveToX}
                            onBulkMoveToYChange={setBulkMoveToY}
