                            onScaleSelected={handleObjectManagerBulkScale}
                            onBulkRotateAngleChange={setBulkRotateAngle}
                            onRotateSelected={handleObjectManagerBulkRotate}
                            onMirrorSelected={handleObjectManagerBulkMirror}
